import type { Command } from "commander";

import { diffKeys } from "../utils/dictionary.js";
import { readFilesOutput, writeJsonOrStdout } from "../utils/files.js";

interface DiffInputOptions {
  json?: string;
}

export function registerDiffInputCommand(program: Command): void {
  program
    .command("diff-input <path>")
    .option("--json <path>", "Save output to <path> file.")
    .description(
      "Receives a JSON file generated by the files command and compares translations with project usage.",
    )
    .action(async (fileName: string, options: DiffInputOptions) => {
      const report = await readFilesOutput(fileName);
      const inputKeys: Record<string, number> = Object.create(null) as Record<string, number>;

      for (const [key, usage] of Object.entries(report.input)) {
        inputKeys[key] = usage.amount;
      }

      const response: Record<string, Record<string, Record<string, number>>> =
        Object.create(null) as Record<string, Record<string, Record<string, number>>>;

      for (const [language, translations] of Object.entries(report.translations)) {
        console.log("Getting difference between input files and " + language + ".");
        const [inputOnly, languageOnly] = diffKeys(inputKeys, translations);
        response[language] = {
          ["in input files, not in language " + language]: inputOnly,
          ["in " + language + ", not in input files"]: languageOnly,
        };
      }

      await writeJsonOrStdout(options.json, response);
    });
}
